import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getTopProviders } from '../services/api';

export default function HomePage() {
  const [keyword, setKeyword] = useState('');
  const [topProviders, setTopProviders] = useState([]);
  const navigate = useNavigate();

  const categories = ['Appliance', 'Cleaning', 'Electrical'];

  useEffect(() => {
    const fetchProviders = async () => {
      try {
        const data = await getTopProviders();
        setTopProviders(data);
      } catch (err) {
        console.error('Failed to fetch top providers', err);
      }
    };
    fetchProviders();
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    if (keyword.trim()) {
      navigate(`/search/${keyword}`);
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>FixIt - Service Marketplace</h1>

      {/* Search Section */}
      <section style={{ marginBottom: '30px' }}>
        <h2>Search Services</h2>
        <form onSubmit={handleSearch} style={{ display: 'flex', gap: '10px' }}>
          <input 
            type="text" 
            placeholder="Search by title, category, description..." 
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            style={{ padding: '10px', width: '300px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
          <button type="submit" style={{ padding: '10px 20px', cursor: 'pointer', background: '#007BFF', color: '#fff', border: 'none', borderRadius: '4px' }}>
            Search
          </button>
        </form>
      </section>

      {/* Categories Section */}
      <section style={{ marginBottom: '30px' }}>
        <h2>Service Categories</h2>
        <div style={{ display: 'flex', gap: '15px' }}>
          {categories.map((cat) => (
            <div 
              key={cat} 
              onClick={() => navigate(`/category/${cat}`)}
              style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px', cursor: 'pointer', minWidth: '120px', textAlign: 'center', background: '#f9f9f9' }}
            >
              <h3>{cat}</h3>
            </div>
          ))}
        </div>
      </section>

      {/* Top Providers Section */}
      <section>
        <h2>Top Rated Providers</h2>
        <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
          {topProviders.length > 0 ? (
            topProviders.map((provider) => (
              <div key={provider._id} style={{ border: '1px solid #ddd', padding: '15px', borderRadius: '8px', width: '250px' }}>
                <h3>{provider.user.name}</h3>
                <p>⭐ {provider.averageRating} / 5</p>
                <p>{provider.totalJobs} jobs completed</p>
              </div>
            ))
          ) : (
            <p>Loading top providers...</p>
          )}
        </div>
      </section>
    </div>
  );
}
